(function() {
    'use strict';

    class ConsultingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Consulting Game';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    title_en: 'Round 1: Portfolio and Staffing Strategy',
                    title_es: 'Ronda 1: Estrategia de Portafolio y Personal',
                    desc_en: 'January 2025. The Colombian economy grows at 4.2%. Your major clients (3 banks, 2 manufacturers, 1 government agency) have active budgets. However, Deloitte just cut standard services pricing by 15% to compete for mid-market deals. Three new RFPs are available: a major bank (USD 1.2M, 6 months), a manufacturing firm (USD 300K, 3 months), and a government contract (USD 200K, 9 months). Decide your hiring, pricing, and bidding strategy.',
                    desc_es: 'Enero 2025. La economia colombiana crece al 4.2%. Sus principales clientes (3 bancos, 2 manufactureras, 1 agencia gubernamental) tienen presupuestos activos. Sin embargo, Deloitte acaba de reducir precios en servicios estandar un 15%. Tres nuevas RFPs disponibles: un banco importante (USD 1.2M), una manufacturera (USD 300K) y un contrato gubernamental (USD 200K). Decida su estrategia de contratacion, precios y licitaciones.',
                    event_en: 'Market Event: Deloitte cuts prices 15% on standard services. Three new RFPs available from banking, manufacturing, and government sectors.',
                    event_es: 'Evento de Mercado: Deloitte reduce precios 15% en servicios estandar. Tres nuevas RFPs disponibles en banca, manufactura y gobierno.'
                },
                {
                    title_en: 'Round 2: Delivery Excellence and Growth',
                    title_es: 'Ronda 2: Excelencia en Entrega y Crecimiento',
                    desc_en: 'Mid-2025. Client satisfaction surveys reveal feedback: great partners but too many junior staff on delivery teams. Three analysts left for corporate jobs at LinkedIn and Bancolombia. Your retention rate dropped to 88%. Accenture launched an AI/Data practice in Bogota with 50 people and USD 8M revenue. A startup called DataMind (10 people, ex-Accenture) is winning AI deals at 30% discount. How will you respond?',
                    desc_es: 'Mediados de 2025. Las encuestas de satisfaccion revelan: buenos socios pero demasiado personal junior en los equipos. Tres analistas se fueron a empleos corporativos. La tasa de retencion bajo al 88%. Accenture lanzo una practica de IA/Datos en Bogota con 50 personas. Una startup DataMind esta ganando contratos de IA con 30% de descuento.',
                    event_en: 'Market Event: Accenture launches AI practice (50 people). Staff turnover pressure increases. Clients demand more senior oversight on teams.',
                    event_es: 'Evento de Mercado: Accenture lanza practica de IA (50 personas). Presion salarial aumenta. Clientes demandan mas supervision senior.'
                },
                {
                    title_en: 'Round 3: Positioning and Scaling',
                    title_es: 'Ronda 3: Posicionamiento y Escalamiento',
                    desc_en: 'Late 2025. Year-to-date revenue is tracking well. Brazil consulting market grows 12% (faster than Colombia at 8%). An acquisition opportunity emerges: a boutique AI/Data firm (12 people, USD 6M revenue) available for USD 4.5M. The labor market has tightened with manager offers at USD 150K (up from 120K). Two existing managers are considering external offers. Make your final strategic decisions.',
                    desc_es: 'Finales de 2025. Los ingresos del ano van bien. El mercado de consultoria en Brasil crece 12% (mas rapido que Colombia al 8%). Oportunidad de adquisicion: firma boutique de IA/Datos (12 personas, USD 6M en ingresos) por USD 4.5M. El mercado laboral se ha ajustado con ofertas de gerente a USD 150K.',
                    event_en: 'Market Event: Acquisition opportunity at USD 4.5M. Labor market tightens significantly. Geographic expansion to Sao Paulo now viable.',
                    event_es: 'Evento de Mercado: Oportunidad de adquisicion por USD 4.5M. Mercado laboral se ajusta significativamente. Expansion a Sao Paulo es viable.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 3200000,
                    partners: 5,
                    managers: 15,
                    analysts: 85,
                    activeClients: 12,
                    utilization: 72,
                    clientSatisfaction: 78,
                    staffRetention: 88,
                    grossMargin: 58,
                    knowledgeLevel: 20,
                    cumulativeRevenue: 0,
                    roundRevenue: 0,
                    revenueHistory: [],
                    profitHistory: [],
                    utilizationHistory: [],
                    satisfactionHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    hireAnalysts: 2,
                    salaryIncrease: 3,
                    trainingBudget: 100,
                    rfpBids: 1,
                    priceAdjustment: 3,
                    knowledgeBudget: 100
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): undo restores state but never re-invokes the view, and
                // language changes should re-render the (localized) briefing/event.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var hireInput = document.getElementById('hireAnalystsInput');
            if (hireInput) decisions.hireAnalysts = parseInt(hireInput.value) || 0;

            var salaryInput = document.getElementById('salarySelect');
            if (salaryInput) decisions.salaryIncrease = parseInt(salaryInput.value) || 0;

            var trainingInput = document.getElementById('trainingInput');
            if (trainingInput) decisions.trainingBudget = parseInt(trainingInput.value) || 0;

            var rfpInput = document.getElementById('rfpInput');
            if (rfpInput) decisions.rfpBids = parseInt(rfpInput.value) || 0;

            var priceInput = document.getElementById('priceSelect');
            if (priceInput) decisions.priceAdjustment = parseInt(priceInput.value) || 0;

            var knowledgeInput = document.getElementById('knowledgeInput');
            if (knowledgeInput) decisions.knowledgeBudget = parseInt(knowledgeInput.value) || 0;

            if (decisions.hireAnalysts < 0 || decisions.hireAnalysts > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('hire_warning'), 'warning'
                );
                return false;
            }

            if (decisions.trainingBudget < 0 || decisions.trainingBudget > 500) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('training_warning'), 'warning'
                );
                return false;
            }

            if (decisions.rfpBids < 0 || decisions.rfpBids > 3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rfp_warning'), 'warning'
                );
                return false;
            }

            if (decisions.knowledgeBudget < 0 || decisions.knowledgeBudget > 500) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('knowledge_warning'), 'warning'
                );
                return false;
            }

            var totalInvestment = (decisions.hireAnalysts * 45000) + (decisions.trainingBudget * 1000) + (decisions.knowledgeBudget * 1000);
            var currentCash = window.mySimulation.state.domainState.cash;
            if (totalInvestment > currentCash * 0.8) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            // FIX(v1.1.0): removed a redundant _updateBriefing() here (it re-rendered
            // the briefing on every validate/preview). The next round is rendered by
            // calculateResults; the decision inputs are static and read above.
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            var d = state.decisions;

            var newHires = d.hireAnalysts;
            var hiringCost = newHires * 45000;

            var retentionMap = {0: 75, 3: 82, 6: 88, 8: 92};
            var retentionRate = retentionMap[d.salaryIncrease] || 82;
            var atRiskStaff = Math.round(ds.analysts * (1 - retentionRate / 100));
            var turnover = Math.max(0, Math.round(atRiskStaff * 0.33));

            ds.analysts = Math.max(10, ds.analysts + newHires - turnover);
            ds.staffRetention = retentionRate;

            var totalBillable = ds.partners + ds.managers + ds.analysts;
            var blendedRate = (ds.partners * 500 + ds.managers * 250 + ds.analysts * 150) / totalBillable;
            var hoursPerRound = 640;
            var availableHours = totalBillable * hoursPerRound;

            var trainingEffect = Math.min(d.trainingBudget * 0.01, 5);
            var hireEffect = newHires * 0.4;
            var knowledgeEffect = Math.max(0, (ds.knowledgeLevel - 20)) * 0.03;
            var ratioBonus = (ds.managers / Math.max(1, ds.analysts)) > 0.18 ? 1.5 : 0;
            var newUtil = 72 + trainingEffect - hireEffect + knowledgeEffect + ratioBonus;
            newUtil = Math.max(55, Math.min(90, Math.round(newUtil * 10) / 10));
            ds.utilization = newUtil;

            var utilizationRate = ds.utilization / 100;
            var billableHours = Math.round(availableHours * utilizationRate);
            var priceMultiplier = 1 + d.priceAdjustment / 100;
            var baseRevenue = Math.round(billableHours * blendedRate * priceMultiplier);

            var winRate = Math.min(0.85, 0.35 + ds.knowledgeLevel / 400);
            var rfpWins = 0;
            for (var b = 0; b < d.rfpBids; b++) {
                var roll = ((state.currentPeriod * 7 + b * 13 + 37) % 100) / 100;
                if (roll < winRate) rfpWins++;
            }
            var newClientRevenue = rfpWins * 350000;

            var churnRate = d.priceAdjustment * 0.018;
            var clientsLost = 0;
            if (churnRate > 0) {
                clientsLost = Math.round(ds.activeClients * churnRate);
                if (clientsLost > 0 && ds.activeClients > 5) {
                    clientsLost = Math.min(clientsLost, Math.max(1, Math.round(ds.activeClients * 0.15)));
                }
            }
            var lostRevenue = clientsLost > 0 ? Math.round(clientsLost * baseRevenue / Math.max(1, ds.activeClients) * 0.6) : 0;

            var totalRevenue = Math.max(0, baseRevenue - lostRevenue + newClientRevenue);

            var salaryMultiplier = 1 + d.salaryIncrease / 100;
            var salaryCost = Math.round((ds.partners * 250000 + ds.managers * 120000 + ds.analysts * 50000) / 3 * salaryMultiplier);
            var trainingCost = d.trainingBudget * 1000;
            var knowledgeCost = d.knowledgeBudget * 1000;
            var overhead = Math.round(35 * 40000 / 3);
            var totalCosts = salaryCost + hiringCost + trainingCost + knowledgeCost + overhead;

            var grossProfit = totalRevenue - totalCosts;
            var margin = totalRevenue > 0 ? Math.round(grossProfit / totalRevenue * 100) : 0;

            ds.cash += grossProfit;
            ds.activeClients = Math.max(3, ds.activeClients - clientsLost + rfpWins);

            ds.knowledgeLevel = Math.min(100, Math.round((ds.knowledgeLevel + d.knowledgeBudget / 50) * 10) / 10);

            var satChange = 0;
            satChange += d.trainingBudget * 0.006;
            satChange -= newHires * 0.4;
            satChange += (ds.managers / Math.max(1, ds.analysts)) * 8;
            satChange += ds.knowledgeLevel * 0.03;
            if (turnover > 3) satChange -= 2;
            ds.clientSatisfaction = Math.max(50, Math.min(100, Math.round(ds.clientSatisfaction + satChange)));

            ds.grossMargin = margin;
            ds.roundRevenue = totalRevenue;
            ds.cumulativeRevenue += totalRevenue;

            ds.revenueHistory.push(totalRevenue);
            ds.profitHistory.push(grossProfit);
            ds.utilizationHistory.push(ds.utilization);
            ds.satisfactionHistory.push(ds.clientSatisfaction);

            // FIX(v1.1.0): advance the briefing synchronously. The previous setTimeout
            // closure read state.currentPeriod AFTER the framework incremented it, so
            // the situation briefing, title, and event text showed round N+2. Guard on
            // state identity so the deep-cloned competition preview never mutates the DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                revenue: totalRevenue,
                costs: totalCosts,
                grossProfit: grossProfit,
                margin: margin,
                newHires: newHires,
                turnover: turnover,
                rfpWins: rfpWins,
                clientsLost: clientsLost,
                utilization: ds.utilization,
                satisfaction: ds.clientSatisfaction,
                totalStaff: totalBillable,
                cash: ds.cash
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('revenueDisplay', 'domainState.roundRevenue',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('staffDisplay', 'domainState.analysts',
                function(v) {
                    var s = window.mySimulation.state;
                    if (s && s.domainState) {
                        var total = s.domainState.partners + s.domainState.managers + s.domainState.analysts;
                        return total.toString();
                    }
                    return v.toString();
                });
            uiManager.bind('clientsDisplay', 'domainState.activeClients');
            uiManager.bind('utilizationDisplay', 'domainState.utilization',
                (v) => Math.round(v) + '%');
            uiManager.bind('marginDisplay', 'domainState.grossMargin',
                (v) => Math.round(v) + '%');
            uiManager.bind('satisfactionDisplay', 'domainState.clientSatisfaction',
                (v) => Math.round(v) + '/100');
            uiManager.bind('retentionDisplay', 'domainState.staffRetention',
                (v) => Math.round(v) + '%');
        }

        getChartConfig() {
            return {
                financialChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Revenue (USD)',
                                data: [],
                                backgroundColor: 'rgba(44,82,130,0.7)',
                                borderColor: '#2c5282',
                                borderWidth: 2
                            },
                            {
                                label: 'Profit (USD)',
                                data: [],
                                backgroundColor: 'rgba(39,174,96,0.7)',
                                borderColor: '#27ae60',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Financial Performance' }
                        },
                        scales: { y: { beginAtZero: true } }
                    }
                },
                operationalChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Utilization (%)',
                                data: [],
                                borderColor: '#e53e3e',
                                backgroundColor: 'rgba(229,62,62,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Client Satisfaction',
                                data: [],
                                borderColor: '#d69e2e',
                                backgroundColor: 'rgba(214,158,46,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Operational Metrics' }
                        },
                        scales: {
                            y: { min: 40, max: 100, beginAtZero: false }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.profitHistory }
                    ]
                },
                operationalChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.utilizationHistory },
                        { data: state.domainState.satisfactionHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var profits = history.map(function(r) { return r.results ? r.results.grossProfit || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var totalProfit = profits.reduce(function(s, v) { return s + v; }, 0);
            var avgMargin = totalRevenue > 0 ? Math.round(totalProfit / totalRevenue * 100) : 0;

            var lastRound = history[history.length - 1];
            var finalUtil = lastRound.results ? lastRound.results.utilization || 0 : 0;
            var finalSat = lastRound.results ? lastRound.results.satisfaction || 0 : 0;

            var revenueScore = Math.min(25, Math.round((totalRevenue / 42000000 - 1) * 100));
            var marginScore = Math.min(25, Math.round(avgMargin * 0.4));
            var utilScore = Math.min(20, Math.round((finalUtil - 55) * 0.57));
            var satScore = Math.min(20, Math.round((finalSat - 50) * 0.4));
            var retScore = 10;
            var totalScore = Math.max(0, revenueScore + marginScore + utilScore + satScore + retScore);

            var performance = 'Needs Improvement';
            if (totalScore >= 70) performance = 'Excellent';
            else if (totalScore >= 55) performance = 'Good';
            else if (totalScore >= 40) performance = 'Satisfactory';

            var insights = [];
            if (avgMargin >= 60) insights.push('Strong margin management through pricing discipline and knowledge investment.');
            if (avgMargin < 55) insights.push('Margins under pressure. Consider raising prices or investing in knowledge reuse to reduce delivery costs.');
            if (finalUtil >= 73 && finalUtil <= 80) insights.push('Utilization in the sweet spot. Well-balanced capacity and demand.');
            if (finalUtil > 85) insights.push('Utilization is dangerously high. Risk of burnout and turnover increases above 80%.');
            if (finalUtil < 68) insights.push('Low utilization suggests excess capacity. Consider more aggressive client development.');
            if (finalSat >= 80) insights.push('High client satisfaction drives retention and referrals. Excellent delivery quality.');
            if (finalSat < 70) insights.push('Client satisfaction needs attention. Invest in senior oversight and training.');

            return {
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                avgMargin: avgMargin,
                finalUtilization: finalUtil,
                finalSatisfaction: finalSat,
                totalScore: totalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.grossProfit < 0) return window.mySimulation.t('hint_loss');
            if (results.turnover > 3) return window.mySimulation.t('hint_turnover');
            if (results.utilization > 85) return window.mySimulation.t('hint_burnout');
            if (results.utilization < 65) return window.mySimulation.t('hint_low_util');
            if (results.satisfaction < 70) return window.mySimulation.t('hint_low_sat');
            if (results.clientsLost > 1) return window.mySimulation.t('hint_churn');
            if (results.margin > 62) return window.mySimulation.t('hint_strong_margin');
            return null;
        }

