        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                if (window.mySimulation && window.mySimulation.currentLanguage) {
                    lang = window.mySimulation.currentLanguage;
                }
            } catch(e) {}

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = round['title_' + lang] || round.title_en;

            var descEl = document.getElementById('briefingText');
            if (descEl) descEl.textContent = round['desc_' + lang] || round.desc_en;

            var eventEl = document.getElementById('eventText');
            if (eventEl) eventEl.innerHTML = round['event_' + lang] || round.event_en;
        }
